let fixture_count = 4
let rejected_count = 42
let baseline = get "payload" (List.hd fixtures)
let defaults = get "default_limits" expected_profile
let literals () =
  require (List.length fixtures=fixture_count && List.length rejected_literals=rejected_count) "Public producer literal census differs";
  require (same expected_profile K.profile) "Public producer capability declaration differs";
  List.iter (fun fixture -> require (same (run (get "payload" fixture)) (get "expected" fixture))
    (Json.string (get "name" fixture)^": complete authority, producer result or presentation differs")) fixtures;
  List.iter (fun fixture ->
    let payload = set "build_request" (get "build_request" fixture) baseline in
    match run payload with
    | _ -> failwith ("Malformed public authority accepted: "^Json.string (get "name" fixture))
    | exception Diagnostic.Error error -> require (error.message=Json.string (get "message" fixture))
        (Json.string (get "name" fixture)^": wrong original error precedence/message: "^error.message)) rejected_literals;
  let request = {Protocol.request_id="public-producer-literal";operation;payload=baseline} in
  (match P.handle Protocol.Verify request with
  | Protocol.Unsupported,None,[error] -> require (error.code="unsupported_operation") "Wrong verifier rejection"
  | _ -> failwith "Verifier performed public synthetic production");
  (match P.handle Protocol.Core request with
  | Protocol.Ok,Some value,[] -> require (same value (get "expected" (List.hd fixtures))) "Public dispatch differs"
  | _ -> failwith "Public producer dispatch failed")
let rejected action = match action () with
  | _ -> failwith "Invalid public producer input accepted"
  | exception Diagnostic.Error _ -> ()
let boundaries () =
  let _,usage = K.handle_with_usage ~executable:Protocol.Core ~request_id:"public-producer-literal" ~operation baseline in
  let parent maximum = W.create ~profile:"public.producer.parent" ~error_code:"public_parent_limit" ~maximum () in
  let exact = parent usage.work_charged in
  require (same (run ~parent:exact baseline) (get "expected" (List.hd fixtures)) && W.remaining exact=0)
    "Public source import, checker, producer or final response escaped ancestor";
  let short = parent (usage.work_charged-1) in
  (match run ~parent:short baseline with
  | _ -> failwith "Public producer returned over its shared ancestor budget"
  | exception Diagnostic.Error error -> require (error.code="public_parent_limit" && W.is_exhaustion short error)
      "Public producer masked ancestor exhaustion");
  List.iter (fun key -> rejected (fun () -> run (set "limits" (set key (Json.int 1) defaults) baseline));
    List.iter (fun bad -> rejected (fun () -> run (set "limits" (set key bad defaults) baseline)))
      [Json.Bool true;Json.Float 1.;Json.int 0;Json.int (-1);Json.Int (Z.pow (Z.of_int 10) 20)])
    ["max_work";"max_request_bytes";"max_report_bytes";"max_report_nodes";"max_monitor_items"];
  rejected (fun () -> run (set "limits" (Json.Object []) baseline));
  rejected (fun () -> run (set "profile" (str "wrong") baseline));
  rejected (fun () -> run (set "unknown" Json.Null baseline));
  let rec cycle = Json.Array [cycle] in rejected (fun () -> run (set "build_request" cycle baseline));
  let rec spine = Json.Null::spine in rejected (fun () -> run (set "build_request" (Json.Array spine) baseline));
  let _,long = K.handle_with_usage ~executable:Protocol.Core ~request_id:(String.make 4096 'x') ~operation baseline in
  require (long.work_charged>usage.work_charged && long.report_bytes>usage.report_bytes)
    "Outer public response identity was omitted from publication";
  require (same (run baseline) (get "expected" (List.hd fixtures))) "Failure changed subsequent public production"
let () = literals ();boundaries ();
  print_endline "Complete synthetic build authority, source precedence, producer records and shared protocol boundaries passed"
